import{_ as s,o as d,c as a,ag as r,j as e}from"./chunks/framework.KxDd3USm.js";const u=JSON.parse('{"title":"07.6 有限自动机：DFA 与 NFA ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"07-程序设计语言基础/06-有限自动机.md","filePath":"07-程序设计语言基础/06-有限自动机.md"}'),o={name:"07-程序设计语言基础/06-有限自动机.md"},c={class:"fig"},l={"data-figure-id":"figure-38",viewBox:"0 0 680 210",width:"100%",style:{"max-width":"680px"},role:"img","aria-label":"DFA 与 NFA 对比。DFA 的一个状态读同一字符只有唯一去向；NFA 可同时去多个状态。子集法将 NFA 的可能状态集合视为 DFA 的一个集合状态，因此识别能力相同。"},n={class:"fig"},g={"data-figure-id":"figure-39",viewBox:"0 0 720 200",width:"100%",style:{"max-width":"720px"},role:"img","aria-label":"子集法转换前后对照：左侧 NFA 初态 0 带 a 自环，并有 ε 边通往状态 1，1 读 a 进入终态 2；右侧子集法得到的 DFA 只有两个集合状态：A 等于闭包 0 即 0 和 1，非终态，B 等于 0、1、2，是终态，A 读 a 进 B，B 读 a 留在 B，识别一个或多个 a"};function i(x,t,h,q,p,A){return d(),a("div",null,[t[4]||(t[4]=r('<h1 id="_07-6-有限自动机-dfa-与-nfa-★★★" tabindex="-1">07.6 有限自动机：DFA 与 NFA ★★★ <a class="header-anchor" href="#_07-6-有限自动机-dfa-与-nfa-★★★" aria-label="Permalink to &quot;07.6 有限自动机：DFA 与 NFA ★★★&quot;">​</a></h1><p><strong>动机</strong>：正规式描述了单词的&quot;模式&quot;，但程序怎么<strong>执行</strong>这个模式？有限自动机（FA）就是正规式的&quot;可执行版本&quot;——词法分析器内部就是一台有限自动机在逐字符扫描。正规式和自动机<strong>描述能力等价</strong>，可互相转换。</p><h3 id="_7-1-定义与五元组" tabindex="-1">7.1 定义与五元组 <a class="header-anchor" href="#_7-1-定义与五元组" aria-label="Permalink to &quot;7.1 定义与五元组&quot;">​</a></h3><p>自动机 M = (S, Σ, δ, s₀, Z)：</p><table tabindex="0"><thead><tr><th>成分</th><th>含义</th></tr></thead><tbody><tr><td>S</td><td>有限<strong>状态集</strong></td></tr><tr><td>Σ</td><td>有穷<strong>输入字母表</strong>（每个元素一个输入字符）</td></tr><tr><td>δ</td><td><strong>转换函数</strong>：当前状态 + 输入字符 → 下一状态</td></tr><tr><td>s₀</td><td>唯一<strong>初态</strong>（s₀ ∈ S）</td></tr><tr><td>Z</td><td><strong>终态集</strong>（可空）</td></tr></tbody></table><p>状态转换图：圆圈是状态，箭头标输入字符表示转移，双圈（或打星）是终态。</p><p><strong>识别规则</strong>：从初态出发，逐个读入字符串的字符沿箭头走；<strong>读完整个串恰好停在终态</strong>，则该串被自动机接受（识别）；中途走不动或读完不在终态，则不接受。</p><p><strong>含 ε 的快判</strong>：如果初态本身也是终态，那么即使一个字符都不读，空串 ε 也已经停在终态，因此自动机接受 ε。若初态上还有能回到终态的循环，则通常识别“0 个或多个”某类片段；看到“初态=终态”先检查选项是否漏掉空串。</p><p>反例：不能因为状态图里“有一条 a 边”就断言最短串一定是 <code>a</code>。若初态画成双圈，长度为 0 的 ε 已经被接受，<code>a</code> 只是另一个可能的串。</p><p><strong>DFA vs NFA（必考区别）</strong>：</p>',10)),e("figure",c,[(d(),a("svg",l,[...t[0]||(t[0]=[r('<defs><marker id="fa" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="var(--ink)"></path></marker></defs><text x="75" y="28" class="t">DFA：同一输入，唯一去向</text><circle cx="100" cy="100" r="25" class="n"></circle><circle cx="240" cy="100" r="25" class="n"></circle><text x="92" y="106" class="t">q0</text><text x="232" y="106" class="t">q1</text><path d="M125 100H214" class="e" marker-end="url(#fa)"></path><text x="164" y="89" class="s">a</text><text x="390" y="28" class="t">NFA：同一输入，可多路</text><circle cx="430" cy="100" r="25" class="n"></circle><circle cx="565" cy="70" r="25" class="n"></circle><circle cx="565" cy="140" r="25" class="n"></circle><text x="422" y="106" class="t">q0</text><text x="557" y="76" class="t">q1</text><text x="557" y="146" class="t">q2</text><path d="M455 94L538 76M455 106L538 134" class="e" marker-end="url(#fa)"></path><text x="480" y="75" class="s">a</text><text x="480" y="143" class="s">a</text><rect x="175" y="167" width="335" height="28" rx="8" fill="var(--gold-soft)" stroke="var(--gold)"></rect><text x="199" y="186" class="t">子集法：{q1,q2} 当作 DFA 的一个状态</text>',20)])])),t[1]||(t[1]=e("figcaption",null,"DFA 单值、NFA 多值（可有 ε 转移）；子集法不丢分支，而是把分支合成集合状态。",-1))]),t[5]||(t[5]=r('<table tabindex="0"><thead><tr><th></th><th>确定有限自动机 DFA</th><th>不确定有限自动机 NFA</th></tr></thead><tbody><tr><td>转移函数</td><td><strong>单值对照</strong>：一个状态面对一个输入符号，转移到的状态<strong>唯一确定</strong></td><td>面对同一输入符号可转移到<strong>多个</strong>状态（一个集合），可有 ε 转移（不读字符就跳）</td></tr><tr><td>识别能力</td><td>与 NFA <strong>等价</strong></td><td>与 DFA 等价（NFA 可用<strong>子集法</strong>确定化成 DFA）</td></tr></tbody></table><p>注：DFA 是 NFA 的特例；两者识别的语言类相同（都恰好是正规式能描述的语言）。这与第 1 课（<a href="/ruankao/01-数据结构与算法/06-算法设计与分析基础.html">算法设计与分析基础</a>）里算法的&quot;确定性&quot;是同一种思想——DFA 每一步走向唯一，模拟它就是照表走。</p><h3 id="_7-2-专题-判定自动机接受哪些串-完整步骤" tabindex="-1">7.2 专题：判定自动机接受哪些串（完整步骤） <a class="header-anchor" href="#_7-2-专题-判定自动机接受哪些串-完整步骤" aria-label="Permalink to &quot;7.2 专题：判定自动机接受哪些串（完整步骤）&quot;">​</a></h3><p><strong>考场三步法</strong>：</p><ol><li><strong>列转移表</strong>：把每个状态对每个输入字符的走向列成表（题干给状态图就照图抄表）。</li><li><strong>逐步走串</strong>：从初态开始，对候选串<strong>逐字符查表</strong>，每步写出当前状态；中途出现&quot;该状态对该字符无转移&quot;则立即拒绝。</li><li><strong>终态核对 + 反向验证</strong>：读完整个串看是否停在终态；再用该自动机对应的<strong>语言特征</strong>（先根据几条路径归纳出&quot;以××开头/结尾&quot;等规律）反向检查一遍，两条路结论一致才落笔。</li></ol><p><strong>例（完整演算）</strong>：DFA 状态转移表如下（q₀ 为初态，q₂ 为唯一终态）：</p><table tabindex="0"><thead><tr><th>状态</th><th>输入 0</th><th>输入 1</th></tr></thead><tbody><tr><td>→q₀</td><td>q₀</td><td>q₁</td></tr><tr><td>q₁</td><td>q₀</td><td>q₂</td></tr><tr><td>*q₂</td><td>q₀</td><td>q₂</td></tr></tbody></table><p><strong>先归纳语言</strong>：观察——只有&quot;连续读入两个 1&quot;才能从 q₀ 经 q₁ 到达 q₂；到了 q₂ 之后读 1 停在 q₂、读 0 回 q₀。所以接受的是<strong>以 11 结尾</strong>的 0、1 串（等价正规式 <code>(0|1)*11</code>）。</p><p><strong>逐步走串</strong>（判 <code>1011</code>）：q₀ --1--&gt; q₁ --0--&gt; q₀ --1--&gt; q₁ --1--&gt; q₂。读完停在终态 q₂ → <strong>接受</strong> ✓。</p><p><strong>反向验证</strong>：<code>1011</code> 以 &quot;11&quot; 结尾，与归纳的语言特征一致 ✓。再判 <code>1101</code>：q₀ --1--&gt; q₁ --1--&gt; q₂ --0--&gt; q₀ --1--&gt; q₁，读完停在 q₁ 非终态 → 拒绝；反向看 <code>1101</code> 以 &quot;01&quot; 结尾，不一致才对（它确实不以 11 结尾）✓。两条路结论吻合。</p><p><strong>给状态图写正规式</strong>：先<strong>归纳语言</strong>（看什么路径能从初态走到终态、走终态前必须经过什么），再用速查表（第六节）把特征写成正规式——以&quot;以 11 结尾&quot;为例：前面任意 <code>(0|1)*</code> ＋ 结尾固定 <code>11</code>，得 <code>(0|1)*11</code>。写完拿一个被接受的串和一个被拒绝的串各回代验一次。</p><h3 id="_7-3-子集法-把-nfa-的-一次多路-变成-dfa-的-集合状态" tabindex="-1">7.3 子集法：把 NFA 的“一次多路”变成 DFA 的“集合状态” <a class="header-anchor" href="#_7-3-子集法-把-nfa-的-一次多路-变成-dfa-的-集合状态" aria-label="Permalink to &quot;7.3 子集法：把 NFA 的“一次多路”变成 DFA 的“集合状态”&quot;">​</a></h3><p>NFA 面对一个输入可以同时走向多个状态；DFA 不允许多选。子集法的核心不是丢掉某条路，而是把“NFA 此刻所有可能状态的集合”当成 DFA 的一个新状态。</p><p><strong>通用步骤</strong>：</p><ol><li>取 NFA 初态的 <strong>ε-闭包</strong>（只走 ε 边能到达的全部状态）作为 DFA 初态；</li><li>对一个集合状态和输入字符 x，让集合中每个 NFA 状态都走一次 x，把所有结果取并集；</li><li>再对结果取 ε-闭包，得到下一个 DFA 集合状态；</li><li>遇到新集合就加入表中，反复处理，直到不再出现新集合；</li><li>集合中只要含 NFA 的任一终态，该集合就是 DFA 终态。</li></ol><p><strong>最小演算·例一（先练主干：没有 ε 边）</strong>：NFA 状态为 <code>{q0,q1}</code>，q0 是初态、q1 是终态，字母表 <code>{a}</code>；转移为 <code>δ(q0,a)={q0,q1}</code>、<code>δ(q1,a)=∅</code>。</p><table tabindex="0"><thead><tr><th>DFA 集合状态</th><th>输入 a 后各状态的去向</th><th>并集结果</th><th>是否终态</th></tr></thead><tbody><tr><td><code>{q0}</code>（初态）</td><td>q0→{q0,q1}</td><td><code>{q0,q1}</code></td><td>否</td></tr><tr><td><code>{q0,q1}</code></td><td>q0→{q0,q1}，q1→∅</td><td><code>{q0,q1}</code></td><td><strong>是</strong>（含 q1）</td></tr></tbody></table><p>得到的 DFA 有两个集合状态：读入第一个 a 后进入终态，以后每读 a 都留在终态，所以识别 <code>a+</code>（一个或多个 a）。反向验证：ε 停在 <code>{q0}</code> 非终态，不接受；<code>a、aa、aaa</code> 都进入或留在 <code>{q0,q1}</code>，接受。</p><p><strong>例二（带 ε 边：ε-闭包真正上场）</strong>。NFA：状态 <code>{0,1,2}</code>，初态 0、终态 2，字母表 <code>{a}</code>；转移：<code>0 --ε--&gt; 1</code>、<code>1 --a--&gt; 2</code>、<code>0 --a--&gt; 0</code>。</p>',19)),e("figure",n,[(d(),a("svg",g,[...t[2]||(t[2]=[r('<defs><marker id="sm-a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="var(--ink)"></path></marker><marker id="sm-g" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="var(--gold)"></path></marker></defs><text class="tt" x="24" y="24">NFA（带 ε 边）</text><text class="tt" x="470" y="24">子集法得到的 DFA</text><path class="e" d="M20 100 H48" marker-end="url(#sm-a)"></path><circle class="n" cx="72" cy="100" r="22"></circle><text class="t" x="72" y="105">0</text><path class="e" d="M58 84 C 52 48, 92 48, 86 84" marker-end="url(#sm-a)"></path><text class="s" x="72" y="52">a</text><path class="ep" d="M94 100 H148" marker-end="url(#sm-g)"></path><text class="s" x="121" y="92">ε</text><circle class="n" cx="170" cy="100" r="22"></circle><text class="t" x="170" y="105">1</text><path class="e" d="M192 100 H246" marker-end="url(#sm-a)"></path><text class="s" x="219" y="92">a</text><circle class="n" cx="272" cy="100" r="22"></circle><circle class="n" cx="272" cy="100" r="16"></circle><text class="t" x="272" y="105">2</text><text class="s" x="147" y="150">双圈 = 终态；虚线金边 = ε（不读字符的免费跳跃）</text><path class="e" d="M330 100 H410" marker-end="url(#sm-a)"></path><text class="s" x="370" y="88">子集法</text><path class="e" d="M412 100 H440" marker-end="url(#sm-a)"></path><circle class="n" cx="464" cy="100" r="24"></circle><text class="t" x="464" y="105">A</text><path class="e" d="M488 100 H560" marker-end="url(#sm-a)"></path><text class="s" x="524" y="92">a</text><circle class="n" cx="586" cy="100" r="24"></circle><circle class="n" cx="586" cy="100" r="18"></circle><text class="t" x="586" y="105">B</text><path class="e" d="M574 78 C 566 42, 606 42, 598 78" marker-end="url(#sm-a)"></path><text class="s" x="586" y="46">a</text><text class="s" x="464" y="150">A = {0,1}</text><text class="s" x="586" y="150">B = {0,1,2} 含终态</text><text class="s" x="360" y="184">ε 不消耗输入字符：它被&quot;吸收&quot;进闭包，转换后的 DFA 里再也没有 ε 边</text>',33)])])),t[3]||(t[3]=e("figcaption",null,'两条出 a 的路（自环、借 ε 先到 1 再进 2）在 DFA 里合成了一次"进 B 并留 B"——分支没有丢，只是打包进了集合。',-1))]),t[6]||(t[6]=r('<p>第一步，<strong>先把每个状态的 ε-闭包算成小表</strong>（闭包 = 从该出发、只许走 ε 边能到的全部状态，含自己）：</p><table tabindex="0"><thead><tr><th>出发状态</th><th>ε-闭包</th><th>走法</th></tr></thead><tbody><tr><td>0</td><td>{0, 1}</td><td>0 自己；0 --ε--&gt; 1；1 再没有 ε 边</td></tr><tr><td>1</td><td>{1}</td><td>没有出发的 ε 边，只有本身</td></tr><tr><td>2</td><td>{2}</td><td>同上</td></tr></tbody></table><p>第二步，按通用步骤（闭包 → 读字符 → 并集 → <strong>再闭包</strong>）逐集合推演：</p><table tabindex="0"><thead><tr><th>集合状态</th><th>含原终态 2？</th><th>输入 a：成员各自去向</th><th>并集</th><th>再取 ε-闭包</th><th>结果</th></tr></thead><tbody><tr><td>A = {0,1}（初态 = 闭包(0)）</td><td>否</td><td>0→{0}，1→{2}</td><td>{0, 2}</td><td>{0,1} ∪ {2} = {0,1,2}</td><td>新状态 B</td></tr><tr><td>B = {0,1,2}</td><td><strong>是 → 终态</strong></td><td>0→{0}，1→{2}，2→∅</td><td>{0, 2}</td><td>仍是 {0,1,2}</td><td>B（不再产生新集合，收工）</td></tr></tbody></table><p>得到上右图的 DFA：A --a--&gt; B，B --a--&gt; B。反向验证语言：ε 停在 A 不接受；一个 a 进 B 接受；更多 a 留 B 接受——与例一同为 <code>a+</code>。<strong>ε 边在这道题里只是把&quot;能提前溜达的状态&quot;打包进集合，从不消耗输入字符。</strong></p><p><strong>闭包口诀：先闭包、再吃字；并完集、又闭包。</strong></p><p><strong>反例演示（易错）</strong>：不能从 <code>{q0,q1}</code> 随便挑 q0 的去向当结果，必须把集合内<strong>所有状态</strong>的去向取并集；也不能把“含终态”误写成“集合必须只剩终态”，只要包含 q1 就是接受状态。</p><p><strong>应试动作</strong>：① 背 DFA/NFA 区别一句话——&quot;DFA 单值、NFA 多值（可含 ε），能力等价&quot;；② 初态也是终态时立刻检查 ε；③ 判串逐字符走，子集法逐集合取并集，集合含任一原终态就标终态；④ 给图写正规式时用“逐字符走 + 归纳语言”双重验证。</p>',8))])}const F=s(o,[["render",i]]);export{u as __pageData,F as default};
